        html += reg("ebitda", "EBITDA", 1e6, Math.round((basis3.ebitda - Math.abs(basis3.umsatz * 0.04)) / 1e6) * 1e6, Math.round((basis3.ebitda + Math.abs(basis3.umsatz * 0.04)) / 1e6) * 1e6);
